              "text": "[Document context]\nTitle: Langfuse pivot count-weighted averages\nSource: langfuse issue 15208 candidate\nPath: /code/langfuse/web/src/features/widgets/utils/pivot-table-utils.ts\nWorkspace: task/sana-farid/pivot-weighting-v2\n\nvalues\n */\nexport function calculateSubtotals(\n  data: DatabaseRow[],\n  metrics: string[],\n): Record<string, number> {\n  const subtotals: Record<string, number> = {};\n  const countMetric = metrics.find(\n    (metric) => detectAggregationType(metric) === \"count\",\n  );\n\nfor (const metric of metrics) {\n    // Extract all values for this metric using the utility function\n    const rowsWithValues = data\n      .map((row) => ({\n        row,\n        value: extractMetricValues(row, [metric])[metric],\n      }))\n      .filter(\n        (entry): entry is { row: DatabaseRow; value: number } =>\n          isNotNullOrUndefined(entry.value),\n      );\n    const values = rowsWithValues.map(({ value }) => value);\n\n// Detect aggregation type and apply correct function\n    const aggregationType = detectAggregationType(metric);\n    const weights =\n      aggregationType === \"avg\" && countMetric\n        ? rowsWithValues.map(({ row }) => {\n            const count = row[countMetric];\n            if (typeof count === \"number\") return count;\n            if (typeof count === \"string\" && count.trim() !== \"\") {\n              const parsedCount = Number(count);\n              return Number.isFinite(parsedCount) ? parsedCount : undefined;\n            }\n            return undefined;\n          })\n        : undefined;\n    const result = applyAggregation(\n      values,\n      aggregationType,\n      weights?.every(isNotNullOrUndefined) ? weights : undefined,\n    );\n\n// Round to 10 decimal places to avoid floating-point precision issues\n    subtotals[metric] = Math.round(result * 1e10) / 1e10;\n  }\n\nreturn subtotals;\n}",
